13	/**
14	 * Query base condivisa dai widget di classifica: utenti con almeno
15	 * un'attività nel mese/sport selezionato, con l'aggregato passato come
16	 * $selectExpression esposto come colonna $alias per l'ordinamento.
17	 */
18	trait BuildsLeaderboardQuery
19	{
20	    use InteractsWithPageFilters;
21	
22	    public function updatedFilters(): void
23	    {
24	        $this->resetPage();
25	    }
26	
27	    protected function getLeaderboardQuery(string $selectExpression, string $alias): Builder
28	    {
29	        $month = $this->filters['month'] ?? null;
30	
31	        // ogni valore selezionato espande al proprio gruppo (es. "Run" include
32	        // anche TrailRun/VirtualRun), vedi SportType::groupMembers()
33	        $sportTypes = collect($this->filters['sportTypes'] ?? [])
34	            ->flatMap(fn (string $value) => SportType::tryFrom($value)?->groupMembers() ?? [$value])
35	            ->unique()
36	            ->values()
37	            ->all();
38	
39	        $monthStart = $month ? Carbon::createFromFormat('Y-m', $month) : Carbon::now();
40	
41	        return User::query()
42	            ->select('users.*')
43	            ->selectRaw("{$selectExpression} as {$alias}")
44	            ->join('activities', 'activities.user_id', '=', 'users.id')
45	            ->whereNull('activities.deleted_at')
46	            ->whereBetween('activities.start_date_local', [
47	                $monthStart->copy()->startOfMonth(),
48	                $monthStart->copy()->endOfMonth(),
49	            ])
50	            ->when(
51	                filled($sportTypes),
52	                fn (Builder $query) => $query->whereIn('activities.sport_type', $sportTypes)
53	            )
54	            ->groupBy('users.id')
55	            ->orderByDesc($alias);
56	    }
57	
58	    /**
59	     * Titolo del widget con immagine accanto al testo (asset in public/images/leaderboard/,
60	     * oggi placeholder in attesa delle immagini definitive). Il testo include
61	     * il nome della tab attiva (es. "Dislivello - Corsa").
62	     */
63	    protected function headingWithImage(string $imagePath, string $label): Htmlable
64	    {
65	        return new HtmlString(sprintf(
66	            '<div class="flex items-center gap-3"><img src="%s" alt="" class="h-64 w-64  rounded object-contain"><span>%s</span></div>',
67	            e(asset($imagePath)),
68	            e($this->appendActiveGroupLabel($label)),
69	        ));
70	    }
71	
72	    private function appendActiveGroupLabel(string $label): string
73	    {
74	        $sportType = SportType::tryFrom(($this->filters['sportTypes'] ?? [])[0] ?? '');
75	
76	        return $sportType ? "{$label} - {$sportType->getLabel()}" : $label;
77	    }
78	}
