44	            ->selectRaw("{$selectExpression} as {$alias}")
45	            ->join('activities', 'activities.user_id', '=', 'users.id')
46	            ->whereNull('activities.deleted_at')
47	            ->whereBetween('activities.start_date_local', [
48	                $monthStart->copy()->startOfMonth(),
49	                $monthStart->copy()->endOfMonth(),
50	            ])
51	            ->when(
52	                filled($sportTypes),
53	                fn (Builder $query) => $query->whereIn('activities.sport_type', $sportTypes)
54	            )
55	            ->groupBy('users.id')
56	            ->orderByDesc($alias);
