61	     * oggi placeholder in attesa delle immagini definitive). Il testo include
62	     * il nome della tab attiva (es. "Dislivello - Corsa").
63	     */
64	    protected function headingWithImage(string $imagePath, string $label): Htmlable
65	    {
66	        return new HtmlString(sprintf(
67	            '<div class="flex items-center gap-3"><img src="%s" alt="" class="h-64 w-64  rounded object-contain"><span>%s</span></div>',
68	            e(asset($imagePath)),
69	            e($this->appendActiveGroupLabel($label)),
70	        ));
